-- =============================================================
-- MonBonAgent — Cleanup 16 démos Perpignan + Seed 84 réels Elne
-- Source : data/commerces-elne.json (OSM ODbL + Sirene Licence ouverte)
-- Status = 'directory' : annuaire local, non partenaire actif
-- =============================================================

begin;

-- 1) Cleanup : 6 offres + 16 commerçants démos Perpignan
delete from public.offers where merchant_id in (select id from public.merchants);
delete from public.merchants;

-- 2) Seed : insertion des commerces réels d'Elne (annuaire OSM + Sirene)

-- 3) Vérification
select count(*) as total_commerces_elne, category, count(*) over (partition by category) as par_categorie
  from public.merchants
  group by category, id
  order by category, name;

commit;